def components(g):
 R,C=len(g),len(g[0]); seen=set(); out=[]
 for r in range(R):
  for x in range(C):
   if (r,x) in seen:continue
   color=g[r][x]; q=[(r,x)]; seen.add((r,x)); cells=[]
   while q:
    a,b=q.pop(); cells.append((a,b))
    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
     u,v=a+da,b+db
