import sqlite3,re,collections,math
p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-high-fresh0/frozen/seen-reference/play/users/u070/system/state/hermes/state.db'; c=sqlite3.connect(f'file:{p}?mode=ro',uri=True); sid='95bdced8-1f4d-4ffd-a863-be552c421bc3'; msgs=c.execute('select content from messages where session_id=? and role="user" order by id',(sid,)).fetchall()
def parse(s):return [list(map(int,l.split())) for l in s.strip().splitlines()]
def comps(g):
 R,C=len(g),len(g[0]);seen=set();out=[]
 for r in range(R):
  for x in range(C):
   if (r,x) in seen:continue
   co=g[r][x];q=[(r,x)];seen.add((r,x));cs=[]
   while q:
    a,b=q.pop();cs.append((a,b))
    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
     u,v=a+da,b+db
     if 0<=u<R and 0<=v<C and (u,v) not in seen and g[u][v]==co:seen.add((u,v));q.append((u,v))
   out.append((co,cs))
 return out
def sig(cs):
 r0=min(r for r,c in cs);r1=max(r for r,c in cs);c0=min(c for r,c in cs);c1=max(c for r,c in cs)
 rows=tuple(sum(1 for r,c in cs if r==rr) for rr in range(r0,r1+1))
 return (r1-r0+1,c1-c0+1,min(rows,rows[::-1]))
def isl(cs):
 s=set(cs);rs=[r for r,c in s];cc=[c for r,c in s];r0,r1=min(rs),max(rs);c0,c1=min(cc),max(cc)
 return len(s)==r1-r0+c1-c0+1 and any(({(r,x) for x in range(c0,c1+1)}|{(y,c) for y in range(r0,r1+1)})==s for r in(r0,r1) for c in(c0,c1))
def ctr(cs):return (sum(r for r,c in cs)/len(cs),sum(c for r,c in cs)/len(cs))
def d(a,b):return math.dist(ctr(a),ctr(b))
def transform(g):
 bg=collections.Counter(x for row in g for x in row).most_common(1)[0][0];objs=[(co,cs) for co,cs in comps(g) if co!=bg];ls=[z for z in objs if isl(z[1])]
 if not ls:return g,None
 key=max(ls,key=lambda z:len(z[1]));gr=collections.defaultdict(list)
 for co,cs in objs:
  if cs!=key[1]:gr[sig(cs)].append((co,cs))
 options=[]
 for s,grp in gr.items():
  if len(grp)<2:continue
  ds=[d(cs,key[1]) for co,cs in grp]
  near=min(ds); far=max(ds)
  score=near/len(grp[0][1])
  options.append((score,near,far,len(grp[0][1]),s,grp,ds))
 if not options:return g,None
 score,near,far,size,s,grp,ds=min(options,key=lambda z:(z[0],-z[2],-z[3]))
 i=max(range(len(grp)),key=lambda i:ds[i]);co,cs=grp[i];out=[row[:] for row in g]
 for r,c in cs:out[r][c]=key[0]
 return out,(key[0],co,len(cs),round(score,3),s)
for txt, in msgs:
 if not txt:continue
 for n,ins,outs in re.findall(r'Demo pair (\d+) input \(\d+x\d+\):\n(.*?)\nDemo pair \1 output \(\d+x\d+\):\n(.*?)(?=\n\nSame instance|\n\nTest input|\Z)',txt,re.S):
