import sqlite3, re, collections
p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-high-fresh0/frozen/seen-reference/play/users/u070/system/state/hermes/state.db'
c=sqlite3.connect(p); sid='95bdced8-1f4d-4ffd-a863-be552c421bc3'
msgs=c.execute("select content from messages where session_id=? and role='user' order by id",(sid,)).fetchall()
def parse_grid(txt, header):
 m=re.search(re.escape(header)+r' \((\d+)x(\d+)\):\n((?:[0-9 ]+\n?)+)',txt)
 return [list(map(int,line.split())) for line in m.group(3).strip().splitlines()] if m else None
def objects(g):
 H,W=len(g),len(g[0]); seen=set();out=[]
 for r in range(H):
  for col in range(W):
   if (r,col) in seen:continue
   color=g[r][col];q=[(r,col)];seen.add((r,col));cells=[]
   for x,y in q:
    cells.append((x,y))
    for a,b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=a<H and 0<=b<W and (a,b) not in seen and g[a][b]==color:
      seen.add((a,b));q.append((a,b))
   r0=min(x for x,y in cells);c0=min(y for x,y in cells);r1=max(x for x,y in cells);c1=max(y for x,y in cells)
   out.append(dict(color=color,cells=set(cells),bbox=(r0,c0,r1,c1),shape=frozenset((x-r0,y-c0) for x,y in cells)))
 return out
def in_bbox(inner, outer):
 a,b,x,y=inner['bbox'];A,B,X,Y=outer['bbox'];return A<=a and B<=b and X>=x and Y>=y
for txt, in msgs:
 if not txt or not re.search(r'Demo pair \d+ input',txt):continue
 d=int(re.search(r'Demo pair (\d+)',txt).group(1));g=parse_grid(txt,f'Demo pair {d} input');o=parse_grid(txt,f'Demo pair {d} output')
 if g is None:continue
 dif={(r,col) for r in range(len(g)) for col in range(len(g[0])) if g[r][col]!=o[r][col]}
 target=next(z for z in objects(g) if z['cells']==dif); dst=o[next(iter(dif))[0]][next(iter(dif))[1]]; objs=objects(g)
 peers=[z for z in objs if z is not target and z['shape']==target['shape']]
 hosts=[z for z in objs if z['color']==dst and any(in_bbox(peer,z) for peer in peers) and not in_bbox(target,z)]
 print(f'D{d}: transformed {target["color"]}->{dst}; peer colors={[z["color"] for z in peers]}; dest-color host bboxes={[z["bbox"] for z in hosts]}')
# locate original test grid in initial user prompt
initial=c.execute("select content from messages where session_id=? and role='user' order by id limit 1",(sid,)).fetchone()[0]
test=parse_grid(initial,'Test input')
objs=objects(test)
print('test dims',len(test),len(test[0]))
# remove background (most common)
bg=collections.Counter(x for row in test for x in row).most_common(1)[0][0]
objs=[z for z in objs if z['color']!=bg]
print('bg',bg,'objects',[(z['color'],len(z['cells']),z['bbox']) for z in objs])
for i,a in enumerate(objs):
 for b in objs[i+1:]:
  if a['shape']==b['shape']:
   for outer,inner in ((a,b),(b,a)):
    hosts=[z for z in objs if z is not outer and z is not inner and in_bbox(inner,z) and not in_bbox(outer,z)]
    if hosts: print('test match:',outer['color'],outer['bbox'],'outside; peer',inner['color'],inner['bbox'],'inside host(s)',[(z['color'],z['bbox']) for z in hosts])

